// Foundation Agent — the autonomous inbox processor.
//
// Triggered every few hours on schedule (7am morning brief / 12pm midday /
// 5pm afternoon / 9pm end-of-day) AND on-demand via /webhook/agent-fire.
//
// What it does:
//   1. Reads unacked thoughts from /data/chatin/ (Synology Chat) and
//      /data/poetech-briefing/inbox/ (direct /webhook/thought).
//   2. Classifies each thought: needs-cloud-claude · needs-local-ollama ·
//      info-only · noise.
//   3. Routes per the TLC firewall: clinical/family-private → Ollama only;
//      everything else can route to Claude/Gemini if needed.
//   4. For Ollama-able tasks: calls local Ollama (sovereign), gets a draft
//      response, writes it to /data/poetech-briefing/responses/ for the
//      next session to pick up.
//   5. For Claude-required tasks: drafts a structured task entry in
//      /data/poetech-briefing/queued-for-claude/ — the next Dispatch
//      session reads the briefing, sees the queued task, executes.
//   6. Posts a digest back to Synology Chat (via outbound webhook if
//      configured) AND pushes a ntfy notification to Darrell's phone.
//
// Per AI-FOUNDATION-INTERNAL-OPERATIONS: this workflow is the recurring
// 'brain check' — the Foundation's heartbeat. It runs whether or not
// Darrell is at the keyboard.

const fs = require('fs');
const path = require('path');
const http = require('http');
const https = require('https');

const CHATIN_DIR = '/data/chatin';
const INBOX_DIR = '/data/poetech-briefing/inbox';
const RESPONSES_DIR = '/data/poetech-briefing/responses';
const QUEUED_DIR = '/data/poetech-briefing/queued-for-claude';
const AGENT_LOG_DIR = '/data/poetech-briefing/agent-log';
const OLLAMA_HOST = process.env.OLLAMA_HOST || 'ollama';
const OLLAMA_PORT = parseInt(process.env.OLLAMA_PORT || '11434', 10);
const OLLAMA_MODEL = process.env.OLLAMA_MODEL || 'qwen2.5:14b-instruct-q4_K_M';
const NTFY_HOST = process.env.NTFY_HOST || 'ntfy';
const NTFY_PORT = parseInt(process.env.NTFY_PORT || '80', 10);
const NTFY_TOPIC = process.env.NTFY_TOPIC || 'poetech-foundation';
const SYNOLOGY_CHAT_INCOMING_URL = process.env.SYNOLOGY_CHAT_INCOMING_URL || ''; // set in env when chat-out is wired

for (const d of [RESPONSES_DIR, QUEUED_DIR, AGENT_LOG_DIR]) {
  try { fs.mkdirSync(d, { recursive: true }); } catch (_) {}
}

function now() { return new Date().toISOString(); }
function readDirSafe(dir) { try { return fs.readdirSync(dir); } catch (_) { return []; } }
function readJsonSafe(p) { try { return JSON.parse(fs.readFileSync(p, 'utf8')); } catch (_) { return null; } }
function statSafe(p) { try { return fs.statSync(p); } catch (_) { return null; } }

// Collect unacked thoughts from both sources from last 48h.
const sinceMs = Date.now() - 48 * 3600_000;
const thoughts = [];
for (const f of readDirSafe(CHATIN_DIR)) {
  if (!f.endsWith('.json') || f.startsWith('_')) continue;
  const p = path.join(CHATIN_DIR, f);
  const s = statSafe(p);
  if (!s || s.mtimeMs < sinceMs) continue;
  const rec = readJsonSafe(p);
  if (!rec) continue;
  const n = rec.normalized || {};
  const text = (n.text || '').trim();
  if (!text) continue;
  // Check if this chat thought already has a response/queued entry.
  const fileKey = f.replace(/\.json$/, '');
  if (fs.existsSync(path.join(RESPONSES_DIR, fileKey + '.json'))) continue;
  if (fs.existsSync(path.join(QUEUED_DIR, fileKey + '.json'))) continue;
  thoughts.push({ source: 'synology-chat', captured_at: rec.captured_at, text, sender: n.sender, file_key: fileKey });
}
for (const f of readDirSafe(INBOX_DIR)) {
  if (!f.endsWith('.json')) continue;
  const rec = readJsonSafe(path.join(INBOX_DIR, f));
  if (!rec || rec.ack_at) continue;
  thoughts.push({ source: 'webhook-inbox', captured_at: rec.captured_at, text: rec.text, id: rec.id, file_key: rec.id });
}

function classify(text) {
  const t = text.toLowerCase();
  // TLC firewall — clinical / family-private content stays local.
  if (/\b(tlc|therapy|counsel|clinical|patient|client session|christina'?s clinical|christina'?s patients)\b/.test(t)) return 'ollama-only';
  if (/\b(child|kids?|christiana|cpoe|mrspoe06)\b.{0,40}\b(diary|journal|private|venting|crying)\b/.test(t)) return 'ollama-only';
  // Explicit routing tokens.
  if (/@claude\b|\bclaude code\b|\bship\b|\bcommit\b|\bpush\b|\bcode change\b/.test(t)) return 'needs-claude';
  if (/@ollama\b|\bsummariz/.test(t)) return 'ollama-preferred';
  if (/^(thx|thanks|noted|got it|ok)\b/.test(t)) return 'info-only';
  // Default: try Ollama first; escalate to Claude if it can't.
  return 'ollama-first-then-escalate';
}

async function callOllama(prompt) {
  return new Promise(resolve => {
    const body = JSON.stringify({ model: OLLAMA_MODEL, prompt, stream: false, options: { temperature: 0.3, num_predict: 512 } });
    const req = http.request({
      host: OLLAMA_HOST, port: OLLAMA_PORT, path: '/api/generate', method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body) },
      timeout: 30000
    }, res => {
      let data = '';
      res.on('data', c => { data += c; });
      res.on('end', () => {
        try {
          const j = JSON.parse(data);
          resolve({ ok: true, response: j.response || '', model: j.model || OLLAMA_MODEL });
        } catch (_) { resolve({ ok: false, error: 'parse failed', raw: data.slice(0, 200) }); }
      });
    });
    req.on('error', e => resolve({ ok: false, error: String(e) }));
    req.on('timeout', () => { req.destroy(); resolve({ ok: false, error: 'timeout' }); });
    req.write(body);
    req.end();
  });
}

async function pushNtfy(title, body, priority, tags) {
  return new Promise(resolve => {
    const opts = {
      host: NTFY_HOST, port: NTFY_PORT, path: '/' + NTFY_TOPIC, method: 'POST',
      headers: {
        'Title': title, 'Priority': String(priority || 3),
        'Tags': (tags || ['speech_balloon']).join(','), 'Content-Type': 'text/plain'
      }, timeout: 5000
    };
    const req = http.request(opts, res => resolve({ ok: res.statusCode < 400 }));
    req.on('error', () => resolve({ ok: false }));
    req.on('timeout', () => { req.destroy(); resolve({ ok: false }); });
    req.write(body);
    req.end();
  });
}

async function postToSynologyChat(text) {
  if (!SYNOLOGY_CHAT_INCOMING_URL) return { ok: false, error: 'SYNOLOGY_CHAT_INCOMING_URL not configured' };
  return new Promise(resolve => {
    const u = new URL(SYNOLOGY_CHAT_INCOMING_URL);
    const lib = u.protocol === 'https:' ? https : http;
    const body = 'payload=' + encodeURIComponent(JSON.stringify({ text }));
    const req = lib.request({
      host: u.hostname, port: u.port || (u.protocol === 'https:' ? 443 : 80), path: u.pathname + u.search,
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded', 'Content-Length': Buffer.byteLength(body) },
      timeout: 8000
    }, res => resolve({ ok: res.statusCode < 400 }));
    req.on('error', () => resolve({ ok: false }));
    req.on('timeout', () => { req.destroy(); resolve({ ok: false }); });
    req.write(body);
    req.end();
  });
}

const processed = [];
for (const t of thoughts) {
  const cls = classify(t.text);
  const out = { ...t, classified: cls, processed_at: now() };

  if (cls === 'info-only') {
    out.action = 'noted';
  } else if (cls === 'needs-claude') {
    // Queue for next Dispatch session.
    out.action = 'queued-for-claude';
    out.task = { prompt: t.text, source: t.source, captured_at: t.captured_at };
    try { fs.writeFileSync(path.join(QUEUED_DIR, t.file_key + '.json'), JSON.stringify(out, null, 2)); } catch (_) {}
  } else {
    // ollama-only OR ollama-preferred OR ollama-first-then-escalate
    const sys = 'You are the PoeTech Family OS Foundation Agent running on the family NAS. You operate under THE-WAY / MIND-OF-CHRIST / ANXIETY-CLARITY foundations: every response answers what/when/why/how with assistance and guidance. Be terse, faith-rooted, useful. If you cannot fully handle a request, end with the literal token ESCALATE_TO_CLAUDE and a one-line reason.';
    const prompt = sys + '\n\n---\n\nDarrell wrote: ' + t.text + '\n\nRespond.';
    const r = await callOllama(prompt);
    out.action = r.ok ? 'ollama-responded' : 'ollama-failed';
    out.ollama_response = r.response || '';
    if (r.ok && /ESCALATE_TO_CLAUDE/.test(r.response) && cls !== 'ollama-only') {
      out.action = 'queued-for-claude';
      out.task = { prompt: t.text, ollama_initial_response: r.response, source: t.source, captured_at: t.captured_at };
      try { fs.writeFileSync(path.join(QUEUED_DIR, t.file_key + '.json'), JSON.stringify(out, null, 2)); } catch (_) {}
    } else if (r.ok) {
      try { fs.writeFileSync(path.join(RESPONSES_DIR, t.file_key + '.json'), JSON.stringify(out, null, 2)); } catch (_) {}
    }
  }
  processed.push(out);
}

// Compose a digest for Darrell.
const counts = { total: processed.length, noted: 0, ollama: 0, queued: 0, failed: 0 };
for (const p of processed) {
  if (p.action === 'noted') counts.noted += 1;
  else if (p.action === 'ollama-responded') counts.ollama += 1;
  else if (p.action === 'queued-for-claude') counts.queued += 1;
  else if (p.action === 'ollama-failed') counts.failed += 1;
}

const digestLines = ['Foundation Agent · ' + now()];
digestLines.push('Thoughts seen: ' + counts.total + ' · Ollama handled: ' + counts.ollama + ' · Queued for Claude: ' + counts.queued + ' · Noted: ' + counts.noted + (counts.failed ? ' · Failed: ' + counts.failed : ''));
if (counts.queued > 0) digestLines.push('Open Dispatch and Claude will pick up the queue automatically.');
for (const p of processed.slice(0, 5)) {
  const preview = (p.text || '').slice(0, 80) + (p.text && p.text.length > 80 ? '…' : '');
  digestLines.push('• [' + p.action + '] ' + preview);
}
const digest = digestLines.join('\n');

if (counts.total > 0) {
  await pushNtfy('PoeTech Foundation digest', digest, counts.queued > 0 ? 4 : 3, ['speech_balloon']);
  await postToSynologyChat(digest);
}

const log = { ran_at: now(), counts, processed };
const safeTs = log.ran_at.replace(/[:.]/g, '-');
try { fs.writeFileSync(path.join(AGENT_LOG_DIR, safeTs + '.json'), JSON.stringify(log, null, 2)); } catch (_) {}

return [{ json: log }];
